  "With mips": {"ca": "Amb mips", "es": "Con mips"},
  "Uncompressed RGBA, 4 bytes per pixel.": {"ca": "RGBA sense comprimir, 4 bytes per píxel.", "es": "RGBA sin comprimir, 4 bytes por píxel."},
